/** Project lat/lng into fractional [col, row] grid coordinates. */
export function projectToGrid(lat: number, lng: number): [number, number] {
  const col = ((lng + 180) / 360) * WORLD_GRID.cols;
  const row = ((WORLD_GRID.latTop - lat) / (WORLD_GRID.latTop - WORLD_GRID.latBottom)) * WORLD_GRID.rows;
  return [col, row];
}
